/* Teacher dashboard: reports generated by the real .docx export (and the real progress file) are read back by teacher-dashboard.html */
const T = require('./_h');
const fs = require('fs'), os = require('os'), path = require('path');
const OUT = process.env.OUT || os.tmpdir();
const JSZip = require(path.join(__dirname, 'fixtures/jszip-3.10.1.min.js'));

const STUDENTS = [
  { name: 'Ana Diaz', period: '2', et: 10.4, ctrl: 27.1, frq: 3, wrong: [0, 3] },
  { name: 'Ben Okoro', period: '2', et: 10.4, ctrl: 27.1, frq: 2, wrong: [0, 1, 3] },     // same key results as Ana
  { name: 'Cy Lee', period: '4', et: 8.9, ctrl: 31.5, frq: 4, wrong: [0] },
];

async function makeStudent(b, srv, st, dir, via) {
  const ctx = await b.newContext({ viewport: { width: 1366, height: 768 } });
  await T.routeLibs(ctx);
  await ctx.addInitScript(s => { try { localStorage.setItem('aplab:student', JSON.stringify({ name: s.name, period: s.period })); localStorage.setItem('aplab:tour', JSON.stringify({ seen: true, v: 1 })); } catch (e) { /* ignore */ } }, st);
  const p = await ctx.newPage(); p.errors = [];
  p.on('pageerror', e => p.errors.push(e.message));
  await p.goto(srv.url + 'lab05.html#analyze'); await p.waitForTimeout(700);
  // pre-lab answers (5 questions), key results and a written answer, then reload so the page renders them
  await p.evaluate(s => {
    const right = [6, 0, 0, 10.5, 0.125, 0.25, 0, 0], wrong = [99, 1, 1, 99, 99, 99, 1, 1], state = {}; for (let i = 0; i < 8; i++) { const ok = !s.wrong.includes(i); state[i] = { value: ok ? right[i] : wrong[i], correct: ok }; }
    Lab.store.set('quiz:prelab', state);
    Lab.keyResult('et50-co2', { label: 'ET₅₀ (with CO₂)', value: s.et, unit: 'min', part: 'float-assay' });
    Lab.keyResult('et50-ctrl', { label: 'ET₅₀ (no CO₂)', value: s.ctrl, unit: 'min', part: 'float-assay' });
    Lab.keyResult('frq-score', { label: 'FRQ self-score', value: s.frq, unit: 'of 4' });
  }, st);
  await p.locator('section.step.is-current textarea[data-save]').first().fill('My answer, ' + st.name); await p.waitForTimeout(700);
  await p.goto(srv.url + 'lab05.html#submit'); await p.reload(); await p.waitForTimeout(900);
  const ds = await p.evaluate(() => Lab.identity.seed.datasetId);
  const file = path.join(dir, st.name.replace(/\W+/g, '_') + (via === 'json' ? '_progress.json' : '.docx'));
  if (via === 'json') {
    await p.locator('details.move-work summary').click();
    const [dl] = await Promise.all([p.waitForEvent('download'), p.getByRole('button', { name: 'Save progress file' }).click()]);
    await dl.saveAs(file);
  } else {
    const b64 = await p.evaluate(async () => { const blob = await Lab.report.docx(); const buf = new Uint8Array(await blob.arrayBuffer()); let s = ''; for (let i = 0; i < buf.length; i += 8192) s += String.fromCharCode.apply(null, buf.subarray(i, i + 8192)); return btoa(s); });
    fs.writeFileSync(file, Buffer.from(b64, 'base64'));
  }
  T.ok(p.errors.length === 0, st.name + ': export without errors ' + p.errors.join('|'));
  await ctx.close();
  return { file, ds };
}

(async () => {
  const srv = await T.serve(), b = await T.launch();
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'dash-'));
  const ana = await makeStudent(b, srv, STUDENTS[0], dir, 'docx');
  const ben = await makeStudent(b, srv, STUDENTS[1], dir, 'docx');
  const cy = await makeStudent(b, srv, STUDENTS[2], dir, 'json');

  // --- the .docx carries the payload ---
  const zip = await JSZip.loadAsync(fs.readFileSync(ana.file));
  const custom = await zip.file('docProps/custom.xml').async('string');
  T.ok(/aplab_payload_000/.test(custom), 'docx has aplab_payload custom properties');
  const chunks = (custom.match(/aplab_payload_\d+/g) || []).length;
  T.ok(chunks >= 1, `payload stored in ${chunks} piece(s)`);
  T.ok(!!zip.file('word/document.xml'), 'docx is still a normal Word document');
  const docXml = await zip.file('word/document.xml').async('string');
  T.ok(/Key results/.test(docXml) && /ET₅₀ \(with CO₂\)/.test(docXml) && /10\.4 min/.test(docXml), 'report has a Key results table');

  // extra files for the dashboard: a "Dee Fox" progress file copied from Ana (same Dataset ID), an old-format file, and bad files
  const anaPayload = JSON.parse(fs.readFileSync(cy.file, 'utf8'));
  T.ok(anaPayload.app === 'aplab' && anaPayload.datasetId === cy.ds && anaPayload.keyResults.length === 3 && anaPayload.quizzes[0].questions.length === 8 && anaPayload.parts.total > 0, 'progress file carries identity, Dataset ID, key results, quiz, parts');
  const old = JSON.parse(JSON.stringify(anaPayload)); ['datasetId', 'keyResults', 'quizzes', 'parts', 'partList', 'labTitle', 'exportedAt'].forEach(k => delete old[k]); old.student = { name: 'Old Format', period: '4' }; old.data['keyres:et50-co2'].value = 7.7; old.data['keyres:et50-ctrl'].value = 30.2;
  fs.writeFileSync(path.join(dir, 'old_format_progress.json'), JSON.stringify(old));
  const extraZip = new JSZip(); extraZip.file('word/document.xml', '<w:document/>'); fs.writeFileSync(path.join(dir, 'plain.docx'), await extraZip.generateAsync({ type: 'nodebuffer' }));
  fs.writeFileSync(path.join(dir, 'broken.docx'), Buffer.from('this is not a zip file'));
  fs.writeFileSync(path.join(dir, 'notes.txt'), 'hello');
  fs.writeFileSync(path.join(dir, 'other.json'), JSON.stringify({ app: 'something-else', v: 1 }));
  fs.writeFileSync(path.join(dir, 'bad.json'), '{ nope');

  // Dee Fox: a copy of Ana's data under another name, so Dataset ID and key results match Ana's
  const dee = JSON.parse(JSON.stringify(anaPayload)); dee.student = { name: 'Dee Fox', period: '2' }; dee.datasetId = ana.ds;
  dee.keyResults.forEach(k => { if (k.id === 'et50-co2') k.value = 10.4; if (k.id === 'et50-ctrl') k.value = 27.1; });
  fs.writeFileSync(path.join(dir, 'Dee_Fox_progress.json'), JSON.stringify(dee));

  // --- the dashboard ---
  const ctx = await b.newContext({ viewport: { width: 1366, height: 900 }, acceptDownloads: true });
  await T.routeLibs(ctx);
  const d = await ctx.newPage(); const errs = [];
  d.on('pageerror', e => errs.push(e.message)); d.on('console', m => { if (m.type() === 'error' && !/gc\.zgo|net::|Failed to load resource|fonts\./.test(m.text())) errs.push(m.text()); });
  await d.goto(srv.url + 'teacher-dashboard.html'); await d.waitForTimeout(600);
  T.ok(/Nothing is uploaded/.test(await d.locator('.privacy').innerText()), 'privacy note: nothing is uploaded');
  T.ok(await d.locator('#empty').isVisible() && await d.locator('#sample').isVisible(), 'empty state with a Load sample data button');
  const reqs = []; d.on('request', r => { if (r.method() !== 'GET' || !/127\.0\.0\.1/.test(r.url())) reqs.push(r.method() + ' ' + r.url()); });

  const names = f => ['Ana_Diaz.docx', 'Ben_Okoro.docx', 'Cy_Lee_progress.json', 'old_format_progress.json', 'Dee_Fox_progress.json', 'plain.docx', 'broken.docx', 'notes.txt', 'other.json', 'bad.json'].map(n => path.join(dir, n));
  await d.setInputFiles('#files', names());
  await d.waitForSelector('table.grid', { timeout: 8000 }); await d.waitForTimeout(500);

  const grid = await d.evaluate(() => { const t = document.querySelector('table.grid'); const heads = [...t.querySelectorAll('thead th')].map(x => x.textContent.trim()); const rows = [...t.querySelectorAll('tbody tr')].map(tr => [...tr.children].map(c => c.textContent.replace(/\s+/g, ' ').trim())); return { heads, rows, tables: document.querySelectorAll('table.grid').length, title: document.querySelector('.labblock h2').textContent }; });
  console.log(JSON.stringify(grid.heads));
  T.ok(grid.tables === 1 && /Lab 5/.test(grid.title), 'one grid, grouped under Lab 5: ' + grid.title.trim());
  T.ok(['Student', 'Class', 'Dataset ID', 'Parts done', 'ET₅₀ (with CO₂) (min)', 'ET₅₀ (no CO₂) (min)', 'FRQ self-score', 'Pre-lab', 'Submitted'].every(h => grid.heads.includes(h)), 'columns: student, class, dataset ID, parts, key results, FRQ, pre-lab, submitted');
  T.ok(grid.rows.length === 5, '5 students (2 docx + 3 json): ' + grid.rows.map(r => r[0]).join(', '));
  const row = n => grid.rows.find(r => r[0].startsWith(n));
  T.ok(row('Ana Diaz') && row('Ana Diaz')[2] === ana.ds && /^\d+\/\d+$/.test(row('Ana Diaz')[3]), 'Ana: Dataset ID from the report matches the page (' + ana.ds + '), parts ' + (row('Ana Diaz') || [])[3]);
  T.ok(row('Ana Diaz')[4] === '10.4' && row('Ana Diaz')[5] === '27.1' && /^3 /.test(row('Ana Diaz')[6]), 'Ana: key results and FRQ score ' + row('Ana Diaz').slice(4, 7).join(' / '));
  T.ok(row('Ana Diaz')[7] === '6/8' && row('Cy Lee')[7] === '7/8', 'pre-lab scores (Ana 6/8, Cy 7/8)');
  T.ok(row('Cy Lee')[2] === cy.ds, 'Cy: progress file, Dataset ID ' + cy.ds);
  T.ok(/^[2-9A-Z]{3}-[2-9A-Z]{3}$/.test(row('Old Format')[2]) && row('Old Format')[3] === '—', 'old-format file: Dataset ID computed, parts unknown');
  // duplicates
  const flags = n => (row(n) || []).slice(-1)[0];
  T.ok(/Same Dataset ID as Dee Fox/.test(flags('Ana Diaz')) && /Same Dataset ID as Ana Diaz/.test(flags('Dee Fox')), 'shared Dataset ID flagged on both rows');
  T.ok(/Identical key results to .*Ben Okoro/.test(flags('Ana Diaz')) && /Identical key results to .*Ana Diaz/.test(flags('Ben Okoro')), 'identical key results flagged');
  T.ok(flags('Cy Lee') === '' && flags('Old Format') === '', 'honest students are not flagged');
  // skipped
  const skipped = await d.evaluate(() => [...document.querySelectorAll('#skipped li')].map(l => l.textContent.replace(/\s+/g, ' ').trim()));
  T.ok(skipped.length === 5, '5 skipped files listed: ' + skipped.length);
  const sk = n => skipped.find(s => s.startsWith(n)) || '';
  T.ok(/no Lab Bench data/.test(sk('plain.docx')) && /Could not open/.test(sk('broken.docx')) && /Only .docx/.test(sk('notes.txt')) && /Not a Lab Bench file/.test(sk('other.json')) && /Not valid JSON/.test(sk('bad.json')), 'each skipped file has its own reason');
  // pre-lab misses
  const miss = await d.evaluate(() => [...document.querySelectorAll('.misses li')].map(li => ({ pct: parseInt(li.querySelector('.pct').textContent, 10), q: li.querySelector('.q').textContent, meta: li.querySelector('.meta').textContent })));
  T.ok(miss.length === 8, '8 pre-lab questions listed');
  T.ok(miss.every((m, i) => i === 0 || miss[i - 1].pct >= m.pct), 'sorted worst-first: ' + miss.map(m => m.pct + '%').join(' '));
  T.ok(miss[0].pct === 100 && /molecules of O2 are released/.test(miss[0].q), 'worst question first (100% missed) with its text: ' + miss[0].q.slice(0, 60));
  T.ok(miss[1].pct === 50 && /2 of 4 students missed it/.test(miss[1].meta) && miss[2].pct === 25, 'next: 50% (' + miss[1].meta + '), then 25%');
  await d.screenshot({ path: OUT + '/dash-1366.png', fullPage: true });

  // sort
  await d.locator('button.sort', { hasText: 'Dataset ID' }).click();
  let order = await d.evaluate(() => [...document.querySelectorAll('table.grid tbody th')].map(x => x.textContent));
  const ids = await d.evaluate(() => [...document.querySelectorAll('table.grid tbody td.mono')].map(x => x.textContent));
  T.ok(ids.join() === ids.slice().sort().join(), 'sort by Dataset ID ascending');
  await d.locator('button.sort', { hasText: 'Dataset ID' }).click();
  const ids2 = await d.evaluate(() => [...document.querySelectorAll('table.grid tbody td.mono')].map(x => x.textContent));
  T.ok(ids2.join() === ids.slice().reverse().join(), 'second click sorts descending');
  T.ok(await d.locator('th[aria-sort="descending"]').count() === 1, 'aria-sort set');
  await d.locator('button.sort', { hasText: /^ET₅₀ \(with CO₂\)/ }).click();
  const ets = await d.evaluate(() => [...document.querySelectorAll('table.grid tbody tr')].map(tr => tr.children[4].textContent).filter(x => x !== '—').map(Number));
  T.ok(ets.join() === ets.slice().sort((a, b) => a - b).join(), 'sort by a key result column numerically ' + ets.join(' '));
  // filters
  await d.selectOption('#f-class', '4');
  let shown = await d.evaluate(() => [...document.querySelectorAll('table.grid tbody th')].map(x => x.textContent));
  T.ok(shown.length === 2 && shown.every(n => /Cy Lee|Old Format/.test(n)), 'class filter: period 4 → ' + shown.join(', '));
  await d.selectOption('#f-class', '');
  await d.fill('#f-q', 'ben'); shown = await d.evaluate(() => [...document.querySelectorAll('table.grid tbody th')].map(x => x.textContent));
  T.ok(shown.length === 1 && /Ben/.test(shown[0]), 'name search');
  await d.fill('#f-q', '');
  // CSV
  const [dl] = await Promise.all([d.waitForEvent('download'), d.click('#csv')]);
  const csvPath = path.join(dir, 'grid.csv'); await dl.saveAs(csvPath);
  const csv = fs.readFileSync(csvPath, 'utf8').replace(/^﻿/, '');
  const lines = csv.trim().split(/\r?\n/);
  T.ok(dl.suggestedFilename() === 'lab-bench-class-grid.csv' && lines.length === 6, 'CSV download: header + 5 rows (' + dl.suggestedFilename() + ')');
  T.ok(/^Lab,Student,Class,Dataset ID,Parts done,Parts total,Lab 5: ET₅₀ \(with CO₂\) \(min\),/.test(lines[0]) && /FRQ self-score/.test(lines[0]) && /Flags,Dataset owner$/.test(lines[0]), 'CSV header: ' + lines[0].slice(0, 90));
  T.ok(lines.some(l => l.startsWith('Lab 5,Ana Diaz,2,' + ana.ds) && l.includes(',10.4,27.1,')) && lines.some(l => /Same Dataset ID as Dee Fox/.test(l)), 'CSV rows carry values and flags');
  await d.selectOption('#f-class', '4');
  const [dl2] = await Promise.all([d.waitForEvent('download'), d.click('#csv')]); await dl2.saveAs(csvPath);
  T.ok(fs.readFileSync(csvPath, 'utf8').trim().split(/\r?\n/).length === 3, 'CSV follows the filters');
  await d.selectOption('#f-class', '');
  T.ok(reqs.length === 0, 'no uploads or non-GET requests: ' + reqs.join(', '));
  await d.screenshot({ path: OUT + '/dash-1366-top.png' });

  // clear, then sample data
  await d.click('#clear'); T.ok(await d.locator('table.grid').count() === 0, 'Clear everything empties the grid');
  await d.click('#sample'); await d.waitForSelector('table.grid');
  const sample = await d.evaluate(() => ({ tables: document.querySelectorAll('table.grid').length, pills: document.querySelectorAll('.pill.sample').length, banner: !document.getElementById('sample-banner').hidden, flagged: document.querySelectorAll('tr.is-flagged').length, misses: document.querySelectorAll('.misses').length }));
  T.ok(sample.tables === 3 && sample.pills >= 28 && sample.banner && sample.flagged >= 4 && sample.misses === 3, 'sample data: 3 labs, every row labelled Sample, banner, flags ' + JSON.stringify(sample));
  await d.selectOption('#f-lab', 'lab09');
  T.ok(await d.locator('table.grid').count() === 1, 'lab filter');
  await d.selectOption('#f-lab', '');
  await d.screenshot({ path: OUT + '/dash-sample-1366.png', fullPage: true });
  T.ok(errs.length === 0, 'dashboard no errors ' + errs.join('|'));

  // 400px dark
  const m = await b.newContext({ viewport: { width: 400, height: 800 }, colorScheme: 'dark' }); await T.routeLibs(m);
  const dm = await m.newPage(); await dm.goto(srv.url + 'teacher-dashboard.html'); await dm.click('#sample'); await dm.waitForSelector('table.grid');
  T.ok(await dm.evaluate(() => document.documentElement.scrollWidth <= innerWidth), 'no sideways page scroll at 400px');
  await dm.screenshot({ path: OUT + '/dash-sample-400-dark.png', fullPage: true });

  // offline: once loaded, everything still works with the network off
  const off = await b.newContext({ viewport: { width: 1000, height: 800 }, acceptDownloads: true }); await T.routeLibs(off);
  const op = await off.newPage(); await op.goto(srv.url + 'teacher-dashboard.html'); await op.waitForFunction(() => /ready/.test(document.getElementById('reader').textContent));
  await off.setOffline(true);
  await op.setInputFiles('#files', [ana.file, path.join(dir, 'Dee_Fox_progress.json')]); await op.waitForSelector('table.grid');
  T.ok(await op.locator('table.grid tbody tr').count() === 2, 'works offline once loaded');

  await b.close(); srv.close();
  T.done('t23-dashboard');
})();
